using Microsoft.EntityFrameworkCore;
namespace Society.Api;

public static class ApplicationDocumentEndpoints
{
    static async Task<MemberApplication> Authorized(Guid tenant, Guid id, AppDb db, Access a) { var application = await db.MemberApplications.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); if (application.UserId != a.UserId && !await a.Can(tenant, "members.approve", application.ChapterId) && !await a.Can(tenant, "members.write", application.ChapterId)) throw new AccessDeniedException(); return application; }
    public static void Map(RouteGroupBuilder t)
    {
        t.MapGet("/applications/{id:guid}/documents", async (Guid tenant, Guid id, AppDb db, Access a) => { await Authorized(tenant, id, db, a); return await db.MemberDocuments.Where(d => d.TenantId == tenant && d.ApplicationId == id).OrderBy(d => d.CreatedAt).Select(d => new { d.Id, d.Name, d.Length, d.ContentType, d.CreatedAt }).ToListAsync(); });
        t.MapPost("/applications/{id:guid}/documents", async (Guid tenant, Guid id, HttpRequest request, AppDb db, Access a, IObjectStore store) => { var application = await Authorized(tenant, id, db, a); if (application.UserId != a.UserId) throw new AccessDeniedException(); if (application.Status is not ("Draft" or "Changes Requested")) throw new DomainException("Save a draft or use a changes-requested application to attach documents"); if (request.ContentLength is null or > 2097152) throw new DomainException("Use a PNG or PDF smaller than 2 MB"); using var input = new MemoryStream(); await request.Body.CopyToAsync(input); var bytes = input.ToArray(); string type; byte[] file; if (bytes.AsSpan().StartsWith(new byte[] { 137, 80, 78, 71 })) { file = AssetEndpoints.SanitizePng(bytes); type = "image/png"; } else if (bytes.Length > 20 && System.Text.Encoding.ASCII.GetString(bytes, 0, 5) == "%PDF-" && System.Text.Encoding.ASCII.GetString(bytes, Math.Max(0, bytes.Length - 1024), Math.Min(1024, bytes.Length)).Contains("%%EOF")) { file = bytes; type = "application/pdf"; } else throw new DomainException("Use a valid PNG or PDF document"); var name = request.Query["name"].ToString(); if (string.IsNullOrWhiteSpace(name) || name.Length > 160 || name.Any(char.IsControl)) throw new DomainException("Name the document"); var doc = new MemberDocument { TenantId = tenant, ApplicationId = id, Name = name, ContentType = type, Kind = "Supporting", Length = file.Length, UploadedBy = a.UserId }; await store.Put(tenant, doc.Id, file); db.MemberDocuments.Add(doc); a.Audit(tenant, "application.document.uploaded", doc.Id); await db.SaveChangesAsync(); return Results.Ok(new { doc.Id }); });
        t.MapGet("/applications/{id:guid}/documents/{document:guid}", async (Guid tenant, Guid id, Guid document, AppDb db, Access a, IObjectStore store) => { await Authorized(tenant, id, db, a); var doc = await db.MemberDocuments.SingleOrDefaultAsync(d => d.TenantId == tenant && d.ApplicationId == id && d.Id == document) ?? throw new AccessDeniedException(); a.Audit(tenant, "application.document.downloaded", document); await db.SaveChangesAsync(); return Results.File(store.Open(tenant, document), doc.ContentType, doc.Name + (doc.ContentType == "application/pdf" ? ".pdf" : ".png")); });
        t.MapGet("/applications/{id:guid}/history", async (Guid tenant, Guid id, AppDb db, Access a) => { await Authorized(tenant, id, db, a); return await db.MembershipDecisions.Where(d => d.TenantId == tenant && d.ApplicationId == id).OrderBy(d => d.At).Select(d => new { d.Id, d.Decision, d.Comment, d.Permission, d.ReviewerRoles, d.OrganizationId, d.DocumentIds, d.At, reviewer = db.Users.Where(u => u.Id == d.ReviewerId).Select(u => u.FullName).First() }).ToListAsync(); });
    }
}
